130	            String bib,
131	            Long finishTimeMs,
132	            List<CheckpointRow> checkpoints) {
133	        Map<String, SnapshotCheckpointRow> byCode = new LinkedHashMap<>();
134	        for (SnapshotCheckpointRow detail : snapshot.checkpoints()) {
135	            if (detail.bib().equals(bib)) {
136	                byCode.put(detail.checkpointCode(), detail);
137	            }
138	        }
139	        List<CheckpointPassResponse> passes = checkpoints.stream()
140	                .map(checkpoint -> {
141	                    SnapshotCheckpointRow detail = byCode.get(checkpoint.checkpointCode());
142	                    if (detail == null) {
143	                        return new CheckpointPassResponse(
144	                                checkpoint.checkpointCode(), checkpoint.position(), null, null);
145	                    }
146	                    return new CheckpointPassResponse(
147	                            detail.checkpointCode(), detail.position(),
148	                            detail.elapsedMillis(), detail.timingId());
149	                })
150	                .toList();
151	        return new RunnerTimingResponse(
152	                snapshot.raceId(), bib, snapshot.version(), finishTimeMs, passes);
153	    }
154	}
