 * @param createdAt       提交时间，Unix毫秒时间戳
 */
public record CheckpointTimingRow(
        String timingId,
        String raceId,
        String bib,
        String checkpointCode,
        int position,
        long elapsedMillis,
        ExclusionReason exclusionReason,
        long createdAt
) implements TimingView {
}

